def upper_bound(values, target):
    left = 0
    right = len(values)
    while left < right:
        middle = left + (right - left) // 2
        if values[middle] <= target:
            left = middle + 1
        else:
            right = middle
    return left

def binary_last(values, target):
    position = upper_bound(values, target) - 1
    if position >= 0 and values[position] == target:
        return position
    return -1

