def lower_trace(values, target):
    left = 0
    right = len(values)
    trace = []
    while left < right:
        middle = left + (right - left) // 2
        trace.append([left, right, middle, values[middle]])
        if values[middle] < target:
            left = middle + 1
        else:
            right = middle
    return {"position": left, "trace": trace}

